/* Campaign measurements use simulation seconds; demand is identical in shifts 1 and 2. */
const POWERUPS=[
{id:'syrup',name:'Faster Syrup Dispenser',cost:18,icon:'syrup',benefit:'Syrup flows 35% faster.',strength:'Shortens syrup preparation.',weakness:'Does not help an oven backlog. Faster flow needs a careful release.'},
{id:'milk',name:'Faster Milk Dispenser',cost:20,icon:'milk',benefit:'Milk flows 35% faster.',strength:'Reduces hands-on milk time.',weakness:'Customers waiting for food will still wait.'},
{id:'coffee',name:'Faster Coffee Dispenser',cost:22,icon:'coffee',benefit:'Coffee flows 35% faster.',strength:'Speeds up the largest coffee pour.',weakness:'Does not fix wrong ingredients or delayed handoffs.'},
{id:'oven',name:'Faster Oven',cost:38,icon:'oven',benefit:'Bake each item in 12 seconds instead of 20.',strength:'Helps when baked items hold up orders.',weakness:'Offers no benefit for coffee-only orders.'},
{id:'capacity',name:'Better Oven Capacity',cost:45,icon:'capacity',benefit:'A third oven slot lets three orders bake together.',strength:'Adds capacity when both existing slots are occupied.',weakness:'An unused extra slot adds no speed.'},
{id:'layout',name:'Improved Workstation Layout',cost:28,icon:'layout',benefit:'Places the pouring stations side by side in ticket order: Syrup → Milk → Coffee. The reach/setup delay before pouring drops from 1.5 seconds to 0.3 seconds.',strength:'Saves 1.2 seconds each time you enter a pouring station. A setup bar shows the time saved.',weakness:'Does not speed up liquid flow, toppings or the oven. It helps most when switching often.'},
{id:'display',name:'Better Order Display',cost:24,icon:'display',benefit:'The active station’s requested ingredient gets a clear ticket-matching badge.',strength:'Makes ingredients easier to find and reduces selection mistakes.',weakness:'You still pour manually; equipment is not faster.'},
{id:'guide',name:'Easier Quality Guide Lines',cost:30,icon:'guide',benefit:'A shaded target band shows the existing acceptable fill range.',strength:'Makes underfilling and overfilling easier to avoid.',weakness:'No extra capacity; the scoring tolerance stays the same.'},
{id:'helper',name:'Extra Barista',cost:10,icon:'helper',rental:true,benefit:'Reserve a drink-making barista for the next shift. $10 covers the entire shift.',strength:'Prepares one untouched, accepted drink at a time while you work elsewhere.',weakness:'Must be paid again each shift. You still manage the shared oven and handoffs.'}
];
class CampaignCafe extends QueueCafe{
 constructor(shift=1,upgrades=[],cash=45,helper=false){super();this.shift=shift;this.upgrades=new Set(upgrades);this.cash=cash;this.busyTime=0;this.workerTime=0;this.queueOnlyArea=0;this.maxWaiting=0;this.stationDelay=Object.fromEntries(['order',...FIELDS,'baking','handoff'].map(k=>[k,0]));this.setupUntil=0;this.activity=null;this.recorded=false;this.rushAt=shift===3?120:180;this.rushShown=false;this.helper=helper;this.helperUnlocked=shift>1;this.ovenSlots=Array(this.upgrades.has('capacity')?3:2).fill(null);if(helper)this.costs=10;this.arrivals=shift===3?[0,24,48,72,96,120,135,150,165,180,195,210,225,240,255,270,285]:[0,30,60,90,120,150,180,200,220,240,260,280];this.seed=814;}
 addOrder(){const o=super.addOrder();if(this.shift===3&&o.recipe.coffee&&!o.recipe.bakery){o.recipe.bakery=MENU.bakery[(o.id-1)%3];o.type='combo';o.price+=o.recipe.bakery==='Breakfast Sandwich'?3.5:o.recipe.bakery==='Croissant'?1.75:1.5;}return o;}
 get arrivalRate(){return this.shift===3?(this.time<120?2.5:4):(this.time<180?2:3);}
 stageFor(o){if(!o.accepted)return 'order';if(this.ready(o))return 'handoff';if(o.recipe.coffee){const next=FIELDS.find(k=>o.fills[k]===undefined);if(next)return next;}return 'baking';}
 canPour(k,o=this.active){return this.time>=this.setupUntil&&super.canPour(k,o);}
 loadOven(slot,item,o=this.active){if(!Number.isInteger(slot)||slot<0||slot>=this.ovenSlots.length||this.ovenSlots[slot]||!MENU.bakery.includes(item)||!this.canStart('baking',o))return false;const job={id:o.id,key:'baking',item,slot,started:this.time,duration:this.upgrades.has('oven')?12:20,worker:'oven'};this.ovenSlots[slot]={...job,ready:false};this.jobs.push(job);this.syncOven();return true;}
 hire(){if(this.helper||!this.helperUnlocked||this.cash+this.profit<10)return false;this.helper=true;this.costs+=10;return true;}
 tick(dt){if(this.finished||!Number.isFinite(dt)||dt<=0)return;const d=Math.min(dt,this.duration-this.time),q=this.orders.length;this.queueOnlyArea+=this.orders.filter(o=>!o.accepted).length*d;this.workerTime+=d*(this.helper?2:1);if(this.activity||this.time<this.setupUntil)this.busyTime+=d;if(this.jobs.some(j=>j.worker==='helper'))this.busyTime+=d;for(const o of this.orders)this.stationDelay[this.stageFor(o)]+=d;super.tick(dt);if(this.helper)this.costs-=d*.03;this.events=this.events.filter(e=>e.type!=='rush');if(this.time>=this.rushAt&&!this.rushShown){this.rushShown=true;this.helperUnlocked=true;this.events.push({type:'rush'});}this.maxWaiting=Math.max(this.maxWaiting,this.orders.filter(o=>!o.accepted).length);this.rushIds=this.arrivals.flatMap((t,i)=>t>=this.rushAt&&i<this.id?[i+1]:[]);}
 report(){const n=this.served.length,mean=k=>n?this.served.reduce((v,o)=>v+o[k],0)/n:0;return {shift:this.shift,served:n,arrived:this.id,unfinished:this.orders.length,wait:mean('wait'),throughput:this.time?n/this.time*60:0,satisfaction:mean('satisfaction'),quality:mean('accuracy'),profit:this.profit,tips:this.tips,utilization:this.workerTime?Math.min(100,100*this.busyTime/this.workerTime):0,queue:this.time?this.queueArea/this.time:0,maxQueue:this.peakQueue,time:this.time,delays:{...this.stationDelay}};}
 mission(){const r=this.report(),goals=[{label:'Serve at least 5 with satisfaction above 80%',done:r.served>=5&&r.satisfaction>80,detail:`${r.served} served · ${Math.round(r.satisfaction)}% satisfaction`},{label:'Complete at least 80% of the shift’s orders',done:r.served>=Math.ceil(this.arrivals.length*.8),detail:`${r.served}/${this.arrivals.length} served`},{label:'Keep order accuracy at 90% or higher',done:r.served>0&&r.quality>=90,detail:`${Math.round(r.quality)}% accuracy`}];return {goals,points:goals.filter(g=>g.done).length*5,promoted:this.finished&&goals.every(g=>g.done)};}
}
